import torch, numpy as np, json

def writer_names():
    names=[]
    for L in range(24):
        names.append(f'model.language_model.layers.{L}.mlp.down_proj.weight')
        if L % 4 == 3:
            names.append(f'model.language_model.layers.{L}.self_attn.o_proj.weight')
        else:
            names.append(f'model.language_model.layers.{L}.linear_attn.out_proj.weight')
    return names

def apply_amp(dname, alpha):
    d = torch.from_numpy(np.load(dname)).float()
    d = d / d.norm()
    for n in writer_names():
        W = load_original(n)
        dW = d @ W  # [cols]
        W2 = W + alpha * torch.outer(d, dW)
        save_edit(n, W2)

